<template><view class="page"><view class="row-between"><view class="page-title">待签到</view><button size="mini" @click="history">签到记录</button></view><view v-for="t in tasks" :key="t.id" class="card" @click="sign(t.id)"><view class="section-title">{{ t.title }}</view><view class="muted">{{ t.description||'无说明' }}</view><view class="muted">发布于 {{ displayTime(t.createdAt) }}</view><button class="primary-btn">去签到</button></view><view v-if="!tasks.length" class="empty">暂无待签到任务</view></view></template>
<script setup lang="ts">import{ref}from'vue';import{onShow}from'@dcloudio/uni-app';import{api}from'@/services/api';import{requireSession}from'@/services/session';import{displayTime}from'@/utils/time';import type{SignTask}from'@/services/types';const tasks=ref<SignTask[]>([]);onShow(async()=>{if(requireSession())tasks.value=await api('/sign-tasks/unsigned')});const sign=(id:number)=>uni.navigateTo({url:`/pages/signIn/signIn?taskId=${id}`});const history=()=>uni.navigateTo({url:'/pages/signDetail/signDetail'})</script>
